CREATE TABLE IF NOT EXISTS employee_exits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE, exit_type text NOT NULL, notice_date date, final_date date, reason text, status text NOT NULL DEFAULT 'planned', handover_status text NOT NULL DEFAULT 'not_started', asset_return_status text NOT NULL DEFAULT 'not_started', access_revocation_status text NOT NULL DEFAULT 'not_started', created_at timestamptz NOT NULL DEFAULT now());